class CompletedLessons:
    def __init__(self, lesson_ids):
        self._items = tuple(lesson_ids)

    def __len__(self):
        return len(self._items)

    def __getitem__(self, index):
        return self._items[index]

    def __iter__(self):
        return iter(self._items)

class ReportSession:
    def __init__(self):
        self.active = False

    def __enter__(self):
        self.active = True
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.active = False
        return False

lessons = CompletedLessons(['loops', 'classes'])
print(len(lessons), lessons[0], list(lessons))
print(list(lessons))
session = ReportSession()
try:
    with session as current:
        print(current.active)
        raise ValueError('demo failure')
except ValueError:
    print(session.active)
